            aOrbiterC = ((aOrbiterC ^ aOrbiterF) ^ 0x2964C252C6D6283EULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 22U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0xA4B6FD2522596D0DULL), 13U);
